  if (!is.numeric(n) || length(n) != 1 || n < 1 || n != floor(n))
    stop("n must be a positive integer")
  invisible(TRUE)
}

# --- Log-concavity check: slopes must be non-increasing ---
check_log_concave <- function(m) {
  if (length(m) >= 2) {
    for (j in 1:(length(m)-1)) {
      if (m[j] < m[j+1] - 1e-7) {
        stop("Non-log-concave density detected: tangent slopes not non-increasing")
      }
    }
  }
  invisible(TRUE)
}

# --- Compute tangent slope and log-density at x ---
eval_logf_deriv <- function(logf, x, h = 1e-7) {
  list(h = logf(x), m = (logf(x + h) - logf(x - h)) / (2 * h))
}

# --- Compute breakpoints z of upper hull ---
compute_z <- function(x, h, m, domain) {
  k <- length(x)
  z <- numeric(k + 1)
  z[1] <- if (is.finite(domain[1])) domain[1] else -Inf
  z[k+1] <- if (is.finite(domain[2])) domain[2] else Inf
  for (i in 1:(k-1)) {
    z[i+1] <- (h[i+1] - h[i] + m[i]*x[i] - m[i+1]*x[i+1]) / (m[i] - m[i+1])
  }
  z
}

# --- Log integral of exp(h + m*(x-xi)) from a to b ---
log_int_exp <- function(h, m, xi, a, b) {
  if (abs(m) < 1e-12) return(h + log(b - a))
  # log(exp(h-m*xi)) + log((exp(m*b)-exp(m*a))/m) for m>0
  # General: log of integral = h - m*xi + log_diff_exp(m*b, m*a) - log(abs(m))
  lo <- min(m*a, m*b); hi <- max(m*a, m*b)
  if (is.infinite(lo) && lo < 0) return(h - m*xi)  # tail integral
  log_val <- (hi - lo) + log(1 - exp(lo - hi))
  h - m*xi + log_val - log(abs(m))
}

# --- Log-sum-exp of a vector ---
log_sum_exp <- function(v) {
  mx <- max(v)
  mx + log(sum(exp(v - mx)))
}

# --- Compute log-normalization constant of upper hull ---
compute_log_norm <- function(x, h, m, z, domain) {
  k <- length(x)
  log_parts <- numeric(k)
  for (i in 1:k) {
    a <- z[i]; b <- z[i+1]
    log_parts[i] <- log_int_exp(h[i], m[i], x[i], a, b)
  }
  log_sum_exp(log_parts)
}

# --- Sample from upper hull given state ---
sample_upper <- function(x, h, m, z, log_norm) {
  k <- length(x)
  # Segment probabilities
  seg_log_probs <- (h - m*x) + m*z[-(k+1)] - log(m)  # not exact, use log_int
  # Recompute properly
  seg_lp <- numeric(k)
  for (i in 1:k) {
    seg_lp[i] <- log_int_exp(h[i], m[i], x[i], z[i], z[i+1]) - log_norm
  }
  seg_probs <- exp(seg_lp)
  seg_probs <- seg_probs / sum(seg_probs)
  # Pick segment
  seg <- sample.int(k, 1, prob = seg_probs)
  # Sample from exp(m_seg*(x - x_seg)) on [z_seg, z_seg+1]
  a <- z[seg]; b <- z[seg+1]
  ms <- m[seg]
  if (abs(ms) < 1e-12) {
    u <- runif(1, a, b)
  } else {
    u <- runif(1)
    if (is.infinite(a) && a < 0) {
      x_val <- x[seg] - log(u)/ms  # left tail
    } else if (is.infinite(b) && b > 0) {
      x_val <- x[seg] - log(1-u)/ms  # right tail
    } else {
      ea <- exp(ms*a); eb <- exp(ms*b)
      x_val <- log(ea + u*(eb - ea)) / ms
    }
  }
  x_val
}
