# Adaptive Rejection Sampler (Gilks & Wild 1992)

# --- log sum exp ---
log_sum_exp <- function(v) {
  mx <- max(v); mx + log(sum(exp(v - mx)))
}

# --- input validation ---
validate_inputs <- function(density_function, domain, n) {
  if (!is.function(density_function)) stop("density_function must be a function")
  if (!is.numeric(domain) || length(domain) != 2) stop("domain must be numeric of length 2")
  if (is.finite(domain[1]) && is.finite(domain[2]) && domain[1] >= domain[2])
