  if (!is.numeric(n) || length(n) != 1 || n < 1 || n != floor(n))
    stop("n must be a positive integer")
  invisible(TRUE)
}

# --- numerical derivative of log-density ---
log_density_deriv <- function(logf, x, h = 1e-6) {
  (logf(x + h) - logf(x - h)) / (2 * h)
}

# --- log-concavity check: tangent slopes must be non-increasing ---
check_log_concave <- function(m) {
  if (length(m) >= 2) {
    for (j in 1:(length(m)-1))
      if (m[j] < m[j+1] - 1e-7)
        stop("Non-log-concave density detected: tangent slopes not non-increasing")
  }
  invisible(TRUE)
}

# --- upper-hull tangent intersection points z ---
compute_z <- function(x, h, m, domain) {
  k <- length(x)
  z <- numeric(k + 1)
  z[1] <- if (is.finite(domain[1])) domain[1] else -Inf
  z[k+1] <- if (is.finite(domain[2])) domain[2] else Inf
  for (i in 1:(k-1))
    z[i+1] <- (h[i+1] - h[i] + m[i]*x[i] - m[i+1]*x[i+1]) / (m[i] - m[i+1])
  z
}

# --- log of integral of exp(h + m*(w-x)) over [a,b] ---
seg_int <- function(hv, mv, xv, a, b) {
  if (abs(mv) < 1e-12) return(hv + log(b - a))
  lo <- min(mv*a, mv*b); hi <- max(mv*a, mv*b)
  if (is.infinite(lo) && lo < 0) hi <- 0  # tail: integral of exp up to 0
  if (hi == 0 && is.infinite(lo)) return(hv - mv*xv)
  log_val <- hi + log(1 - exp(lo - hi))
  hv - mv*xv + log_val - log(abs(mv))
}

# --- log normalization constant of upper hull ---
compute_log_norm <- function(x, h, m, z) {
  k <- length(x); lp <- numeric(k)
  for (i in 1:k) lp[i] <- seg_int(h[i], m[i], x[i], z[i], z[i+1])
  log_sum_exp(lp)
}

# --- sample one point from a single tangent segment ---
sample_seg <- function(mv, xv, a, b) {
  if (abs(mv) < 1e-12) return(runif(1, a, b))
  u <- runif(1)
  if (is.infinite(a) && a < 0) return(b + log(u)/mv)     # left tail, mv>0
  if (is.infinite(b) && b > 0) return(a + log(1-u)/mv)   # right tail, mv<0
  ea <- exp(mv*a); eb <- exp(mv*b)
  a + log(ea + u*(eb - ea))/mv
}

# --- upper hull value H(w) and its segment index ---
hull_value <- function(st, w) {
  z <- st$z; k <- length(st$x)
  for (i in 1:k) if (w >= z[i] && w <= z[i+1]) return(list(H = st$h[i] + st$m[i]*(w - st$x[i]), seg = i))
