log_density_deriv <- function(logf, x, h = 1e-6) (logf(x+h) - logf(x-h)) / (2*h)

check_log_concave <- function(m) {
  if (length(m) >= 2)
    for (j in 1:(length(m)-1))
      if (m[j] < m[j+1] - 1e-7) stop("Non-log-concave density: slopes not non-increasing")
