compute_z <- function(x, h, m, domain) {
  k <- length(x); z <- numeric(k+1)
  z[1] <- if (is.finite(domain[1])) domain[1] else -Inf
  z[k+1] <- if (is.finite(domain[2])) domain[2] else Inf
  for (i in 1:(k-1))
    z[i+1] <- (h[i+1]-h[i]+m[i]*x[i]-m[i+1]*x[i+1])/(m[i]-m[i+1])
  z
}

seg_int <- function(hv, mv, xv, a, b) {
  if (abs(mv) < 1e-12) {
    if (is.infinite(a) || is.infinite(b)) stop("Zero slope on infinite segment")
    return(hv + log(b - a))
  }
  A <- mv*b; B <- mv*a; lo <- min(A,B); hi <- max(A,B)
  if (is.infinite(lo) && lo < 0) return(hv - mv*xv + hi - log(abs(mv)))
  if (is.infinite(hi) && hi > 0) stop("Divergent integral in segment")
  hv - mv*xv + hi + log(1 - exp(lo - hi)) - log(abs(mv))
}

compute_log_norm <- function(x, h, m, z) {
  k <- length(x); lp <- numeric(k)
  for (i in 1:k) lp[i] <- seg_int(h[i], m[i], x[i], z[i], z[i+1])
  log_sum_exp(lp)
}

sample_seg <- function(mv, a, b) {
  if (abs(mv) < 1e-12) return(runif(1, a, b))
  u <- runif(1)
  if (is.infinite(a) && a < 0) return(b + log(u)/mv)
  if (is.infinite(b) && b > 0) return(a + log(u)/mv)
  d <- mv*(b - a)
  if (d > 50) return(b + log(u)/mv)
  if (d < -50) return(a + log(1-u)/mv)
  a + log1p(u*(exp(d)-1))/mv
}

sample_hull <- function(st) {
  k <- length(st$x); lp <- numeric(k)
  for (i in 1:k) lp[i] <- seg_int(st$h[i], st$m[i], st$x[i], st$z[i], st$z[i+1])
  p <- exp(lp - log_sum_exp(lp)); p <- p/sum(p)
  seg <- sample.int(k, 1, prob = p)
  list(w = sample_seg(st$m[seg], st$z[seg], st$z[seg+1]), seg = seg)
