check_hull <- function(logf, st) {
  for (i in 1:length(st$x)) {
    a <- st$z[i]; b <- st$z[i+1]
    if (is.infinite(a) && is.infinite(b)) next
    if (is.infinite(a)) a <- st$x[i] - 1
    if (is.infinite(b)) b <- st$x[i] + 1
    for (t in seq(a, b, length.out = 5)) {
