make_state <- function(logf, x, domain) {
  x <- sort(x); h <- sapply(x, logf)
  if (any(!is.finite(h))) stop("Initial points must have finite log-density")
  m <- sapply(x, function(xi) log_density_deriv(logf, xi))
  check_log_concave(m)
  z <- compute_z(x, h, m, domain)
  st <- list(x=x, h=h, m=m, z=z)
  st$log_norm <- compute_log_norm(x, h, m, z)
  check_hull(logf, st)
