update_state <- function(logf, st, w, domain) {
  x <- sort(c(st$x, w)); h <- sapply(x, logf)
  if (any(!is.finite(h))) return(st)
  m <- sapply(x, function(xi) log_density_deriv(logf, xi))
  check_log_concave(m)
  z <- compute_z(x, h, m, domain)
  if (any(diff(z) <= 0)) stop("Non-log-concave density: non-monotone hull intersections")
  st2 <- list(x=x, h=h, m=m, z=z)
  st2$log_norm <- compute_log_norm(x, h, m, z)
  check_hull(logf, st2)
  st2
}

find_initial_points <- function(logf, domain) {
  if (is.finite(domain[1]) && is.finite(domain[2])) {
    r <- domain[2] - domain[1]; cands <- domain[1] + r*(1:9)/10
  } else if (is.finite(domain[1])) {
    cands <- domain[1] + c(0.1,0.5,1,2,5,10,20)
  } else if (is.finite(domain[2])) {
    cands <- domain[2] - c(20,10,5,2,1,0.5,0.1)
  } else {
    cands <- seq(-5, 5, by = 1)
  }
  valid <- cands[sapply(cands, function(x) is.finite(logf(x)))]
  if (length(valid) < 2) stop("Could not find 2 valid initial points")
  x <- sort(valid)
  m <- sapply(x, function(xi) log_density_deriv(logf, xi))
  if (!is.finite(domain[1]) && m[1] <= 0) {
    for (lx in seq(x[1]-0.5, x[1]-100, by=-0.5)) {
      if (is.finite(logf(lx))) {
        lm <- log_density_deriv(logf, lx)
        if (lm > 0) { x <- sort(c(lx, x)); m <- sapply(x, function(xi) log_density_deriv(logf, xi)); break }
      }
    }
    if (m[1] <= 0) stop("Cannot find positive-slope point for -Inf boundary")
  }
  if (!is.finite(domain[2]) && m[length(m)] >= 0) {
    for (rx in seq(x[length(x)]+0.5, x[length(x)]+100, by=0.5)) {
      if (is.finite(logf(rx))) {
        rm <- log_density_deriv(logf, rx)
        if (rm < 0) { x <- c(x, rx); m <- sapply(x, function(xi) log_density_deriv(logf, xi)); break }
      }
    }
    if (m[length(m)] >= 0) stop("Cannot find negative-slope point for Inf boundary")
  }
  x
}

ars <- function(density_function, domain, n = 1000) {
  validate_inputs(density_function, domain, n)
  logf <- function(x) log(density_function(x))
  st <- make_state(logf, find_initial_points(logf, domain), domain)
  samples <- numeric(n); i <- 1
  while (i <= n) {
    cand <- sample_hull(st); w <- cand$w
    H <- st$h[cand$seg] + st$m[cand$seg]*(w - st$x[cand$seg])
    fw <- logf(w)
    if (!is.finite(fw)) next
    if (log(runif(1)) < fw - H) { samples[i] <- w; i <- i + 1 }
    else st <- update_state(logf, st, w, domain)
  }
  samples
}

test <- function() {
  cat("=== ARS Test Suite ===\n\n")
  n <- 10000; tol <- 4
  results <- list()

  cat("[1/6] Sampling from standard normal N(0,1)...\n")
  set.seed(42); s1 <- ars(dnorm, c(-Inf, Inf), n)
  se1 <- 1/sqrt(n)
  p1 <- abs(mean(s1)) < tol*se1 && abs(sd(s1)-1) < tol*se1
  results[["STANDARD_NORMAL"]] <- p1
  cat(sprintf("  mean=%.4f (exp 0), sd=%.4f (exp 1)\n", mean(s1), sd(s1)))
  cat(sprintf("STANDARD_NORMAL: %s\n\n", ifelse(p1, "PASS", "FAIL")))

  cat("[2/6] Sampling from exponential(rate=1)...\n")
  set.seed(42); s2 <- ars(dexp, c(0, Inf), n)
  se2 <- 1/sqrt(n)
  p2 <- abs(mean(s2)-1) < tol*se2 && abs(sd(s2)-1) < tol*se2
  results[["EXPONENTIAL"]] <- p2
  cat(sprintf("  mean=%.4f (exp 1), sd=%.4f (exp 1)\n", mean(s2), sd(s2)))
  cat(sprintf("EXPONENTIAL: %s\n\n", ifelse(p2, "PASS", "FAIL")))

  cat("[3/6] Sampling from normal(mean=5, sd=2)...\n")
  set.seed(123); s3 <- ars(function(x) dnorm(x, 5, 2), c(-Inf, Inf), n)
  se3 <- 2/sqrt(n)
  p3 <- abs(mean(s3)-5) < tol*se3 && abs(sd(s3)-2) < tol*se3
  results[["NORMAL_SHIFTED"]] <- p3
  cat(sprintf("  mean=%.4f (exp 5), sd=%.4f (exp 2)\n", mean(s3), sd(s3)))
  cat(sprintf("NORMAL_SHIFTED: %s\n\n", ifelse(p3, "PASS", "FAIL")))

  cat("[4/6] Testing input validation (negative n)...\n")
  e4 <- tryCatch({ars(dnorm, c(-Inf,Inf), -1); FALSE}, error=function(e) TRUE)
  results[["VALIDATE_NEGATIVE_N"]] <- e4
  cat(sprintf("  Error caught: %s\n", ifelse(e4, "yes", "no")))
  cat(sprintf("VALIDATE_NEGATIVE_N: %s\n\n", ifelse(e4, "PASS", "FAIL")))

  cat("[5/6] Testing input validation (invalid domain)...\n")
  e5 <- tryCatch({ars(dnorm, c(1,-1), 100); FALSE}, error=function(e) TRUE)
  results[["VALIDATE_BAD_DOMAIN"]] <- e5
  cat(sprintf("  Error caught: %s\n", ifelse(e5, "yes", "no")))
  cat(sprintf("VALIDATE_BAD_DOMAIN: %s\n\n", ifelse(e5, "PASS", "FAIL")))

  cat("[6/6] Testing non-log-concave density detection...\n")
  e6 <- tryCatch({ars(function(x) 1+x^2, c(-1,1), 100); FALSE}, error=function(e) TRUE)
  results[["NON_LOG_CONCAVE"]] <- e6
  cat(sprintf("  Error caught: %s\n", ifelse(e6, "yes", "no")))
  cat(sprintf("NON_LOG_CONCAVE: %s\n\n", ifelse(e6, "PASS", "FAIL")))

  set.seed(42); sn <- ars(dnorm, c(-Inf,Inf), n)
  write.table(sn, "/app/normal_samples.txt", row.names=FALSE, col.names=FALSE)
  set.seed(42); se_s <- ars(dexp, c(0,Inf), n)
  write.table(se_s, "/app/exponential_samples.txt", row.names=FALSE, col.names=FALSE)
  cat("Saved samples to /app/normal_samples.txt and /app/exponential_samples.txt\n\n")

  cat("=== Summary ===\n")
  for (nm in names(results))
    cat(sprintf("  %s: %s\n", nm, ifelse(results[[nm]], "PASS", "FAIL")))
  invisible(results)
}
EOF
echo "File written: $(wc -l < /app/ars.R) lines"
